		createTemplate: (ns) => `apiVersion: v1
kind: LimitRange
metadata:
  name: my-limitrange
  namespace: ${ns}
spec:
  limits:
    # Container: inject defaults when requests/limits are unset, and enforce min/max
    - type: Container
      default:
        cpu: 500m
        memory: 512Mi
      defaultRequest:
        cpu: 100m
        memory: 128Mi
      max:
        cpu: "2"
        memory: 2Gi
      min:
        cpu: 50m
        memory: 64Mi
      maxLimitRequestRatio:
        cpu: "4"
    # Pod: cap the whole pod
    - type: Pod
      max:
        cpu: "4"
        memory: 4Gi
    # PVC: cap volume size
    - type: PersistentVolumeClaim
      max:
        storage: 100Gi
      min:
        storage: 1Gi
`
