//#region src/stores/skillStore.ts
var useSkillStore = defineStore("skills", () => {
	const skills = ref([]);
	const loaded = ref(false);
	async function load() {
		if (loaded.value) return;
		try {
			skills.value = await ListSkills() || [];
		} catch (e) {
			console.error("Failed to load skills:", e);
			skills.value = [];
		}
		loaded.value = true;
	}
	function reload() {
		loaded.value = false;
		return load();
	}
	const enabledSkills = computed(() => skills.value.filter((s) => s.enabled));
	async function toggleEnabled(name) {
		const s = skills.value.find((x) => x.name === name);
		if (!s) return;
		s.enabled = !s.enabled;
		try {
			await SetSkillEnabled(name, s.enabled);
		} catch (e) {
			console.error("Failed to toggle skill enabled:", e);
		}
	}
	async function toggleLocked(name) {
		const s = skills.value.find((x) => x.name === name);
		if (!s) return;
		s.locked = !s.locked;
		try {
			await SetSkillLocked(name, s.locked);
		} catch (e) {
			console.error("Failed to toggle skill lock:", e);
		}
	}
	async function remove(name) {
		const s = skills.value.find((x) => x.name === name);
		if (!s) return;
		if (s.locked) return;
		try {
			await DeleteSkill(name);
			skills.value = skills.value.filter((x) => x.name !== name);
		} catch (e) {
			console.error("Failed to delete skill:", e);
		}
	}
	async function create(name, description, body) {
		try {
			await CreateSkill(name, description, body);
			await reload();
		} catch (e) {
			console.error("Failed to create skill:", e);
			throw e;
		}
	}
	async function save(name, description, body) {
		try {
			await SaveSkill(name, description, body);
			await reload();
		} catch (e) {
			console.error("Failed to save skill:", e);
			throw e;
		}
	}
	async function saveByAgent(name, description, body) {
		await load();
		if (skills.value.some((s) => s.name === name)) await SaveSkill(name, description, body);
		else await CreateSkill(name, description, body);
		await reload();
	}
	async function getBody(name) {
		try {
			return await GetSkillBody(name);
		} catch (e) {
			console.error("Failed to get skill body:", e);
			return "";
		}
	}
	async function openFolder(path) {
		if (!path) return;
		try {
			await OpenPathInExplorer(path);
		} catch (e) {
			console.error("Failed to open skill folder:", e);
		}
	}
	return {
		skills,
		loaded,
		enabledSkills,
		load,
		reload,
		toggleEnabled,
		toggleLocked,
		remove,
		create,
		save,
		saveByAgent,
		getBody,
		openFolder
	};
});
