	function dispose() {
		unsubFirstRun?.();
		unsubFirstRun = null;
	}
	return {
		dataDirInfo,
		status,
		firstRun,
		backendAvailable,
		loadDataDir,
		loadStatus,
		selectDataDir,
		setup,
		unlock,
		switchMode,
		changeMasterPassword,
		reset,
		watchEvents,
		dispose
	};
